mapper.select:
SELECT id, period, status, report_data, markdown, error_msg, generated_at, created_at
FROM expense_reports
WHERE id = #{id}

mapper.update:
UPDATE expense_reports
SET status       = 'DONE',
    report_data  = #{reportData},
    markdown     = #{markdown},
    generated_at = #{generatedAt}
WHERE id = #{id}

UPDATE expense_reports
SET status       = 'FAILED',
    error_msg    = #{errorMsg},
    generated_at = #{generatedAt}
WHERE id = #{id}
